exercises.solution:
programa
{
    funcao inicio()
    {
        cadeia jogo
        inteiro jogadores
        escreva("Jogo: ")
        leia(jogo)
        escreva("Jogadores: ")
        leia(jogadores)
        escreva(jogo, ": ", jogadores, " jogadores")
    }
}
